# [ src/dialogs/ZA02_sod_court_and_strategy/anyone_plyr_cpsq_0_09.py:L1-L5 ] anyone|plyr::cpsq_0->legate_sq_1_01 [no_conditions] {what is it like back home? the refugee nobles are quite unwillin}
[anyone|plyr, "cpsq_0", [
		is_legate
	], "What is it like back home? The refugee nobles are quite unwilling to tell me.", "legate_sq_1_01", [] ],
# [ src/dialogs/ZA02_sod_court_and_strategy/anyone_plyr_cpsq_0_10.py:L1-L5 ] anyone|plyr::cpsq_0->legate_sq_2_01 [no_conditions] {you know much of me, but i don't know you so well. please tell m}
