# [ src/dialogs/ZD01_encounters_battles_and_prisoners/anyone_plyr_party_encounter_hostile_defender_09.py:L1-L5 ] anyone|plyr::party_encounter_hostile_defender->legate_sq_1_01 [no_conditions] {what is it like back home? the refugee nobles are quite unwillin}
[anyone|plyr, "party_encounter_hostile_defender", [
		is_legate
	], "What is it like back home? The refugee nobles are quite unwilling to tell me.", "legate_sq_1_01", [] ],
# [ src/dialogs/ZD01_encounters_battles_and_prisoners/anyone_plyr_party_encounter_hostile_defender_10.py:L1-L5 ] anyone|plyr::party_encounter_hostile_defender->legate_sq_2_01 [no_conditions] {you know much of me, but i don't know you so well. please tell m}
[anyone|plyr, "party_encounter_hostile_defender", [
		is_legate
	], "You know much of me, but I don't know you so well. Please tell me about yourself.", "legate_sq_2_01", [] ],
# [ src/dialogs/ZD01_encounters_battles_and_prisoners/anyone_plyr_party_encounter_hostile_defender_11.py:L1-L5 ] anyone|plyr::party_encounter_hostile_defender->legate_sq_3_01 [no_conditions] {your empire is constantly trying to conquer others. what is the }
[anyone|plyr, "party_encounter_hostile_defender", [
		is_legate
	], "Your empire is constantly trying to conquer others. What is the purpose of all this fighting?", "legate_sq_3_01", [] ],
# [ src/dialogs/ZD01_encounters_battles_and_prisoners/anyone_plyr_party_encounter_hostile_defender_12.py:L1-L5 ] anyone|plyr::party_encounter_hostile_defender->legate_sq_4_01 [no_conditions] {i had a suspicion that my survival and escape wasn't mere luck. }
[anyone|plyr, "party_encounter_hostile_defender", [
		is_legate
	], "I had a suspicion that my survival and escape wasn't mere luck. Did you have your hand in that?", "legate_sq_4_01", [] ],
