# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_plyr_sod_sa_war_room_answer_clock.py:L1-L3 ] trp_sod_strategy_advisor|plyr::sod_sa_war_room_answer->sod_sa_war_room_clock [no_conditions] {how much time do we have before the legion arrives?}
[trp_sod_strategy_advisor|plyr, "sod_sa_war_room_answer", [], "How much time do we have before the Legion arrives?", "sod_sa_war_room_clock", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_sod_sa_war_room_clock.py:L1-L23 ] trp_sod_strategy_advisor::sod_sa_war_room_clock->sod_sa_war_room [store_mul|val_div|store_current_day] {{var}}
[trp_sod_strategy_advisor, "sod_sa_war_room_clock", [
    (store_mul, ":estimated_day", "$g_sod_invasion_begin", "$g_sod_invasion_inaccuracy"),
    (val_div, ":estimated_day", 100),
    (store_current_day, ":today"),
    (store_sub, ":days_left", ":estimated_day", ":today"),
    (try_begin),
      (lt, ":today", "$g_sod_invasion_begin"),
      (try_begin),
        (le, ":days_left", 20),
        (str_store_string, s2, "@very little useful preparation time"),
      (else_try),
        (le, ":days_left", 60),
        (str_store_string, s2, "@a short season of preparation"),
      (else_try),
        (str_store_string, s2, "@time to prepare, if we stop wasting it"),
      (try_end),
      (str_store_string, s1, "@My best estimate still gives us {s2}. Treat that as a lying witness, not scripture. The Legion fed false dates before our homeland fell."),
    (else_try),
      (str_store_string, s1, "@It has begun. The clock is no longer a clock; it is marching iron. Count roads, granaries, allies, and reserve horses now."),
    (try_end),
], "{s1}", "sod_sa_war_room", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_plyr_sod_sa_war_room_answer_allies.py:L1-L3 ] trp_sod_strategy_advisor|plyr::sod_sa_war_room_answer->sod_sa_war_room_allies [no_conditions] {can alliances push the legion back?}
[trp_sod_strategy_advisor|plyr, "sod_sa_war_room_answer", [], "Can alliances push the Legion back?", "sod_sa_war_room_allies", []],
# [ src/dialogs/ZA02_sod_court_and_strategy/trp_sod_strategy_advisor_sod_sa_war_room_allies.py:L1-L45 ] trp_sod_strategy_advisor::sod_sa_war_room_allies->sod_sa_war_room [call_script|assign|assign] {{var}}
[trp_sod_strategy_advisor, "sod_sa_war_room_allies", [
    (call_script, "script_sod_imperial_expedition_calculate_anti_legion_coalition"),
    (assign, ":coalition_strength", reg0),
    (assign, ":friendly_realms", reg1),
    (assign, ":trusted_mini_factions", reg2),
    (assign, ":delay_total", "$g_sod_imperial_delay_total"),
    (store_sub, ":delay_remaining", 90, "$g_sod_imperial_delay_total"),
    (try_begin),
      (faction_slot_ge, "fac_kingdom_6", slot_faction_state, sfs_active),
      (str_store_string, s1, "@Now alliances no longer delay arrival; they decide how many fires the Legion must put out before it reaches your throat. The Imperial Expeditionary Force is not a kingdom in the Calradian sense. It treats diplomacy as reconnaissance before conquest. Use allies as roads, shields, and witnesses."),
    (else_try),
      (ge, ":coalition_strength", 30),
      (gt, ":delay_remaining", 0),
      (try_begin),
        (ge, ":friendly_realms", 2),
        (ge, ":trusted_mini_factions", 2),
        (str_store_string, s2, "@broad enough to use both courts and trusted mini-factions"),
      (else_try),
        (ge, ":friendly_realms", 2),
        (str_store_string, s2, "@strongest among the crowns"),
      (else_try),
        (str_store_string, s2, "@held together mostly by useful trusted mini-factions"),
      (try_end),
      (try_begin),
        (lt, ":delay_total", 30),
        (str_store_string, s3, "@some time"),
      (else_try),
        (lt, ":delay_total", 70),
        (str_store_string, s3, "@a meaningful delay"),
      (else_try),
        (str_store_string, s3, "@nearly all the delay we can hope to steal"),
      (try_end),
      (str_store_string, s1, "@Yes. Your anti-Legion coalition is {s2}. That is enough to fund counter-intelligence, false roads, and border delays. You have already bought {s3}; there may still be room to slow the Legion before it adapts."),
    (else_try),
      (ge, ":coalition_strength", 30),
      (str_store_string, s1, "@You have the coalition, but the delay ledger is spent. From here, allies no longer push the Legion back; they decide whether it meets one realm or a continent braced for impact."),
    (else_try),
      (ge, ":coalition_strength", 15),
      (str_store_string, s1, "@You have the bones of a coalition, but not enough yet to delay the invasion cleanly. Turn a quiet border into a truce, a shared fear into an anti-Imperial league, and a mini-faction favor into scouts or safe roads."),
    (else_try),
      (str_store_string, s1, "@Not yet. You have no reliable coalition. If the Legion arrives while every king sees you as a rival first, they will defeat Calradia one proud fool at a time. Do not send the Legion a treaty. Make allies around it, then make the road here expensive."),
    (try_end),
], "{s1}", "sod_sa_war_room", []],
