# [ src/dialogs/ZB01_lords_politics_and_family/anyone_prison_break_lord_talk_1.py:L1-L3 ] anyone::prison_break_lord_talk_1->prison_break_lord_talk_2 [no_conditions] {who- ...ah, diego. yes, i remember now. he was a great fighter a}
[anyone, "prison_break_lord_talk_1", [], "Who- ...ah, Diego. Yes, I remember now. He was a great fighter and a good mate, but that's a thing of the past. Had you asked me a few years ago, I wouldn't have hesitated to lend him a hand, but I'm afraid that I can't help him now.", "prison_break_lord_talk_2", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_prison_break_lord_talk_2.py:L1-L7 ] anyone|plyr::prison_break_lord_talk_2->prison_break_lord_talk_3 [call_script|call_script|call_script] {what ? you abandon your friend, as simply as that ?}
[anyone|plyr, "prison_break_lord_talk_2", [
  (call_script, "script_succeed_quest", "qst_slave_q1"),
  (call_script, "script_end_quest", "qst_slave_q1"),
  (call_script, "script_change_player_relation_with_faction", "fac_commoners", 5),
  ], "What ? You abandon your friend, as simply as that ?", "prison_break_lord_talk_3", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_prison_break_lord_talk_3.py:L1-L3 ] anyone::prison_break_lord_talk_3->prison_break_lord_talk_4 [no_conditions] {it's not that simple ! i, uh... have developed some business con}
[anyone, "prison_break_lord_talk_3", [], "It's not that simple ! I, uh... have developed some business connections with the Slavers. As such, it would be quite bad for me if I interfered with Diego's case. Look, my wife wanted reliable servants, and there is simply no better place to acquire quality worksforce for a fair price than the slave market. They even gave me a discount ! And it's not like I treat the people bought from them with cruelty, so you shouldn't accuse me of being a bad person.", "prison_break_lord_talk_4", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_prison_break_lord_talk_4.py:L1-L3 ] anyone|plyr::prison_break_lord_talk_4->prison_break_lord_talk_5 [no_conditions] {sure, but still... you seem awful quick to leave diego to his fa}
[anyone|plyr, "prison_break_lord_talk_4", [], "Sure, but still... you seem awful quick to leave Diego to his fate.", "prison_break_lord_talk_5", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_prison_break_lord_talk_5.py:L1-L9 ] anyone::prison_break_lord_talk_5->close_window [call_script|setup_quest_text|str_store_string] {if i were to free him, i could endanger myself and my family as }
[anyone, "prison_break_lord_talk_5", [
  (call_script, "script_store_troop_name_link", s13, "$g_talk_troop"),
  (setup_quest_text, "qst_slave_q2"),
  (str_store_string, s2, "@The lord you spoke with refused to help Diego directly. Return to Diego with the bad news."),
  (assign, "$prison_break", 2),
  (call_script, "script_start_quest", "qst_slave_q2", "$g_talk_troop"),
  ], "If I were to free him, I could endanger myself and my family as well. If you pity him so much, you'll have to free him yourself. If you do, I'll pull some strings so the Slavers won't bother you afterward, but that's all I can do. Now please depart and send word to Diego of our conversation.", "close_window", [(assign, "$g_leave_encounter", 1),]],
# [ src/dialogs/ZA01_startup_and_dispatch/anyone_start_37.py:L1-L6 ] anyone::start->close_window [eq|call_script] {{var}}
[anyone, "start", [
  (eq, "$talk_context", tc_mercenary_base),
  (call_script, "script_get_random_string_for_troop", s68, "$g_talk_troop"),
  ], "{s68}", "close_window", []],
