[anyone|plyr , "pretender_intro_1", [], "My name is {playername}. At your sevice.", "pretender_intro_2", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_pretender_intro_1_02.py:L1-L3 ] anyone|plyr::pretender_intro_1->pretender_intro_2 [no_conditions] {i am {var}. perhaps you have heard of my exploits.}
[anyone|plyr , "pretender_intro_1", [], "I am {playername}. Perhaps you have heard of my exploits.", "pretender_intro_2", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_pretender_intro_2.py:L1-L7 ] anyone::pretender_intro_2->pretender_intro_3 [troop_get_slot|val_sub|val_add] {{var}}
