# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon_after_renounce_peace.py:L1-L18 ] anyone::lord_ask_pardon_after_renounce_peace->lord_pretalk [no_conditions] {excellent. though you strayed from us, {var}, it gladdens all ou}
[anyone, "lord_ask_pardon_after_renounce_peace",
   [],
   "Excellent. Though you strayed from us, {playername}, it gladdens all our hearts that you have found your way back to the right path. I hereby restore your homage to me. Rise once more as an honoured {man/warrior} in my service.", "lord_pretalk",
   [
     (try_for_range, ":cur_center", walled_centers_begin, walled_centers_end),
       (store_faction_of_party, ":cur_center_faction", ":cur_center"),
       (eq, ":cur_center_faction", "fac_player_supporters_faction"),
       (party_slot_eq, ":cur_center", slot_center_faction_when_oath_renounced, "$g_talk_troop_faction"),
       (neq, ":cur_center", "$players_oath_renounced_given_center"),
       (call_script, "script_give_center_to_faction", ":cur_center", "$g_talk_troop_faction"),
     (try_end),

     (call_script, "script_player_join_faction", "$g_talk_troop_faction"),
     (assign, "$player_has_homage", 1),
     (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", 3),
     ]],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon_terms_rejected.py:L1-L11 ] anyone::lord_ask_pardon_terms_rejected->close_window [no_conditions] {then get out of my sight, traitor! begone with you, and do not c}
[anyone, "lord_ask_pardon_terms_rejected",
   [], "Then get out of my sight, traitor! Begone with you, and do not come back!", "close_window",
   [
     (assign, "$g_leave_encounter", 1),
     (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -5),
     (store_current_hours, "$players_oath_renounced_begin_time"),
     (assign, "$players_oath_renounced_given_center", 0),
     (assign, "$players_oath_renounced_terms_state", 0),
     ]],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_lord_talk_15.py:L1-L29 ] anyone|plyr::lord_talk->lord_ask_pardon [neg|troop_slot_ge|lt|this_or_next|eq] {there has been enough blood between me and {var}. name the road }
[anyone|plyr, "lord_talk",
    [
      (neg|troop_slot_ge, "$g_talk_troop", slot_troop_prisoner_of_party, 0),
      (lt, "$g_talk_troop_faction_relation", 0),
      (this_or_next|eq, "$players_kingdom", 0),
      (eq, "$players_kingdom", "fac_player_supporters_faction"),
      #MORDACHAI - allow one to burry the hatchet with their former king
      #(neq, "$players_oath_renounced_against_kingdom", "$g_talk_troop_faction"),
      (assign, ":continue", 1),
      (try_begin),
        (gt, "$supported_pretender", 0),
        (eq, "$supported_pretender_old_faction", "$g_talk_troop_faction"),
        (assign, ":continue", 0),
      (try_end),
      (eq, ":continue", 1),
      (str_store_faction_name, s4, "$g_talk_troop_faction"),

      #MORDACHAI - generate a wider range of responses to the player, with his persuasion skill, charisma, et. al. factors involved
      (store_attribute_level, ":charisma", "trp_player", ca_charisma),
      (store_skill_level, ":persuasion", "skl_persuasion", "trp_player"),
      (store_mul, ":upper_bound", ":persuasion", 10),
      (val_add, ":upper_bound", ":charisma"),
      (val_add, ":upper_bound", 1), #compensate for the range stupidity of the random function
      (assign, ":lower_bound", "$g_talk_troop_relation"),
      (store_random_in_range, reg10, ":lower_bound", ":upper_bound"),
   ],
   "There has been enough blood between me and {s4}. Name the road back to peace.", "lord_ask_pardon", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon.py:L1-L3 ] anyone::lord_ask_pardon->lord_pretalk [lt] {do you indeed, {var}? then go and trip on your sword. give us al}
[anyone, "lord_ask_pardon", [(lt, reg10, -10)], "Do you indeed, {playername}? Then go and trip on your sword. Give us all peace.", "lord_pretalk", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon_02.py:L1-L19 ]
[anyone, "lord_ask_pardon",
    [
      (store_sub, ":hostility", 4, "$g_talk_troop_faction_relation"),
      (val_mul, ":hostility", ":hostility"), #square it
      (store_mul, reg16, ":hostility", 10),
      #MORDACHAI - make their reaction a percentage modifier to the cost
      (assign, reg14, reg10),
      (assign, reg15, reg16),
      (val_mul, reg10, -1),   # invert sign
      (val_add, reg10, 100),  # convert to % multiplier (e.g. +20 = 80, -15 = 115)
      (val_mul, reg16, reg10), # multiply by the % modifier
      (val_div, reg16, 100),  # apply decimal place
      #(display_message, "@reaction was {reg14}, base cost = {reg15}, final cost = {reg16}", debug_color),
    ],
    "Hmm. I could use my considerable influence to arrange a pardon for you, {playername}, "\
    "but there are some who see you as an enemy and will not be satisfied unless you pay tribute."\
    "All in all, you'd need to bring no less than {reg16} denars to make any friends in {s4}.", "lord_ask_pardon_2", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_lord_ask_pardon_2.py:L1-L3 ] anyone|plyr::lord_ask_pardon_2->lord_ask_pardon_tribue_accept [store_troop_gold|ge] {i have the money here. {var} denars.}
[anyone|plyr, "lord_ask_pardon_2", [(store_troop_gold, ":gold", "trp_player"), (ge, ":gold", reg16)], "I have the money here. {reg16} denars.", "lord_ask_pardon_tribue_accept", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_plyr_lord_ask_pardon_2_02.py:L1-L3 ] anyone|plyr::lord_ask_pardon_2->lord_ask_pardon_tribue_deny [no_conditions] {i fear i cannot pay that much.}
[anyone|plyr, "lord_ask_pardon_2", [], "I fear I cannot pay that much.", "lord_ask_pardon_tribue_deny", []],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon_tribue_accept.py:L1-L16 ] anyone::lord_ask_pardon_tribue_accept->close_window [no_conditions] {excellent, {var}. i'll use the coin to smooth the feathers of th}
[anyone, "lord_ask_pardon_tribue_accept", [], "Excellent, {playername}. I'll use the coin to smooth the feathers of those that can oppose your pardon, and I'm sure that word will soon spread that you are no longer an enemy of {s4}.", "close_window",
   [
     (call_script, "script_sod_player_charge_gold", reg16),
     (play_sound, "snd_money_paid"),
     (try_begin),
       (eq, "$players_kingdom", 0),
       (call_script, "script_set_player_relation_with_faction", "$g_talk_troop_faction", 0),
     (else_try),
    #MORDACHAI - bug fix: not enough arguments for script (final argument required!)
       (call_script, "script_diplomacy_start_peace_between_kingdoms", "$g_talk_troop_faction", "$players_kingdom", 1),
     (try_end),
     (assign, "$g_leave_town_outside", 1),
     (assign, "$g_leave_encounter", 1),
     ]],
# [ src/dialogs/ZB01_lords_politics_and_family/anyone_lord_ask_pardon_tribue_deny.py:L1-L3 ] anyone::lord_ask_pardon_tribue_deny->lord_pretalk [no_conditions] {then there's nothing i can do for you, {var}. no silver, no pard}
[anyone, "lord_ask_pardon_tribue_deny", [], "Then there's nothing I can do for you, {playername}. No silver, no pardon.", "lord_pretalk", []],
