                                           (party_is_active, ":quest_target_center"),
                                           (quest_slot_eq, "qst_slavers_escort_merchant_caravan", slot_quest_current_state, 1),
                                           (store_distance_to_party_from_party, ":dist", ":quest_target_center", "$g_encountered_party"),
