[anyone|plyr, "regular_member_talk", [], "Take command of a patrol.", "mate_check_leadership", []],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_mate_check_leadership.py:L1-L49 ] anyone::mate_check_leadership->close_window [call_script|store_skill_level|troop_get_slot] {i will take a patrol and keep close to the company.}
[anyone, "mate_check_leadership",
    [
      (call_script, "script_check_for_patrols"),
      (store_skill_level, ":max_amount", skl_leadership, "trp_player"),
      (troop_get_slot, ":renown", "trp_player", slot_troop_renown),
      (val_div, ":renown", 250),
      (val_add, ":max_amount", ":renown"),
      (try_for_range, ":num", walled_centers_begin, walled_centers_end),
        (party_slot_eq, ":num", slot_town_lord, "trp_player"),
        (val_add, ":max_amount", 1),
      (try_end),
      (gt, ":max_amount", reg0),
    ],
    "I will take a patrol and keep close to the company.", "close_window",
    [
      (store_conversation_troop, ":soldier"),
      (try_begin),
        (gt, ":soldier", 0),
        (party_count_members_of_type, ":soldier_count", "p_main_party", ":soldier"),
        (gt, ":soldier_count", 0),
        (spawn_around_party, "p_main_party", "pt_player_patrol"),
        (assign, ":new_patrol", reg0),
        (gt, ":new_patrol", 0),
        (party_is_active, ":new_patrol"),
        (remove_member_from_party, ":soldier"),
        (party_add_leader, ":new_patrol", ":soldier"),
        (party_set_slot, ":new_patrol", slot_party_type, spt_player_patrol),
        (try_begin),
          (eq, "$g_custom_banner", 1),
          (troop_get_slot, ":flag_icon", "trp_player", slot_troop_custom_banner_map_flag_type),
          (val_max, ":flag_icon", 0),
          (val_add, ":flag_icon", custom_banner_map_icons_begin),
          (party_set_banner_icon, ":new_patrol", ":flag_icon"),
        (else_try),
          (troop_get_slot, ":cur_banner", "trp_player", slot_troop_banner_scene_prop),
          (gt, ":cur_banner", 0),
          (val_sub, ":cur_banner", banner_scene_props_begin),
          (val_add, ":cur_banner", banner_map_icons_begin),
          (party_set_banner_icon, ":new_patrol", ":cur_banner"),
        (try_end),
        (party_set_ai_behavior, ":new_patrol", ai_bhvr_escort_party),
        (party_set_ai_object, ":new_patrol", "p_main_party"),
      (else_try),
        (display_message, "@The patrol could not be placed on the map. Your soldier remains with you.", 0xFFCC66),
      (try_end),
    ]
  ],
# [ src/dialogs/ZZ99_misc_dialogs/anyone_mate_check_leadership_02.py:L1-L3 ] anyone::mate_check_leadership->member_chat [no_conditions] {not yet, captain. your command is stretched too thin to field an}
